"""Build the local comparison viewer from frozen outputs and evaluator records."""
from pathlib import Path
import json,html
ROOT=Path(__file__).parent
h=lambda x:html.escape(str(x))
ASSIGN=json.loads((ROOT/'inputs/assignments.json').read_text())
LABELS={'g01':'evals-B','g05':'evals-A','g03':'isolation-A','g07':'isolation-B','g06':'backpropagation-A','g02':'backpropagation-B','g04':'bayesian_spam-A','g08':'bayesian_spam-B'}
TOPICS={'evals':'AI application evals','isolation':'Transaction isolation','backpropagation':'Backpropagation','bayesian_spam':'Bayesian spam classification'}
DIMS={'reader_fit':'Reader fit','prerequisite_coverage':'Coverage','edge_validity':'Dependencies','granularity':'Granularity','evidence_alignment':'Evidence','research_record_authenticity':'History','application_utility':'Application'}

def build():
 result=json.loads((ROOT/'evaluation/results.json').read_text());graphs={g['label']:g for g in result['graphs']}
 summary=(ROOT/'summary.json')
 meta=json.loads(summary.read_text()) if summary.exists() else {'headline':'Graph-first comparison','description':'Four matched topics; eight independent graph-generation runs. Read the frozen audit below.'}
 out=['''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>DAG-first comparison</title><style>*{box-sizing:border-box}body{margin:0;background:#f5f4f0;color:#101527;font:16px/1.65 system-ui,sans-serif}main{max-width:1300px;margin:auto;padding:42px 24px}h1{font-size:clamp(2rem,4vw,3.5rem);line-height:1.1;letter-spacing:-.04em;max-width:950px}h2{margin-top:40px;font-size:1.6rem}p{max-width:950px}a{color:#2f6c9e;overflow-wrap:anywhere}a:hover{color:#bf3030}:focus-visible{outline:3px solid #bf3030;outline-offset:3px}button{font:inherit;background:white;color:#101527;border:1px solid #bbc1c6;padding:9px 15px;cursor:pointer}button[aria-pressed=true]{background:#101527;color:white}.tabs{display:flex;gap:8px;flex-wrap:wrap;margin:24px 0}.pair{display:grid;grid-template-columns:1fr 1fr;gap:24px}.panel{min-width:0;background:white;border:1px solid #cbd0d3;padding:18px}.panel h3{margin-top:0}.panel p{font-size:.92rem}iframe{display:block;width:100%;height:680px;border:1px solid #cbd0d3;background:#fafafa}table{border-collapse:collapse;width:100%;background:white;font-size:.92rem}td,th{padding:10px 12px;border-bottom:1px solid #cbd0d3;text-align:left}th{background:#ecece7}.table-scroll{overflow:auto}small{color:#55606a}.note{border-left:4px solid #bf3030;padding-left:18px}li{margin:7px 0}.tag{text-transform:uppercase;letter-spacing:.12em;font-size:.75rem;color:#55606a}[hidden]{display:none!important}@media(max-width:800px){.pair{grid-template-columns:1fr}main{padding:28px 18px}iframe{height:560px}}</style></head><body><main><div class="tag">Break It Down · prerequisite graph experiment</div>''', '<h1>'+h(meta['headline'])+'</h1><p>'+h(meta['description'])+'</p>', '<p><a href="results.md">Results and recommendation</a> · <a href="evaluation/blind-review.md">Independent review</a> · <a href="protocol.md">Protocol</a> · <a href="../2026-10-24/index.html">Original report experiment</a></p>', '<p class="note">These are graph-only tests, not a rerun of the full reports or a measurement of human learning. Original frozen scores remain below. Review was partially blinded: two notes leaked condition labels. <a href="evaluation/deviations.md">Limits and deviations</a>.</p>']
 if (ROOT/'evaluation/benchmark-scope-audit.md').exists():out.append('<p><a href="evaluation/benchmark-scope-audit.md">Independent audit of benchmark scope</a></p>')
 if (ROOT/'evaluation/scope-sensitivity.md').exists():out.append('<p><a href="evaluation/scope-sensitivity.md">Separate corrected-scope analysis</a></p>')
 if (ROOT/'evaluation/dimensional-comparison.md').exists():out.append('<p><a href="evaluation/dimensional-comparison.md">Independent comparison across dimensions</a></p>')
 if (ROOT/'repair/results.json').exists():
  repaired=json.loads((ROOT/'repair/results.json').read_text())['graphs']
  out.append('<h2>Focused repair: fresh runs</h2><p>Three failed topics regenerated, plus a new hash-table topic held out from the instruction designer. Fresh evaluator; prospectively corrected scope criteria. These are new observations, not edits to earlier scored graphs. <a href="repair/review.md">Read the audit</a> · <a href="repair/protocol.md">Retest protocol</a> · <a href="repair/skill.txt">Repaired candidate</a></p><div class="table-scroll"><table><thead><tr><th>Topic</th>'+''.join('<th>'+h(v)+'</th>' for v in DIMS.values())+'<th>Verdict</th><th>Artifacts</th></tr></thead><tbody>')
  for g in repaired:
   run=g['label'];title=TOPICS.get(g['topic'],'Hash tables')
   out.append('<tr><th>'+h(title)+'</th>'+''.join('<td>'+h(g['dimensions'].get(d,'NE'))+'</td>' for d in DIMS)+'<td>'+h(g['verdicts']['overall'].replace('_',' '))+'</td><td><a href="runs/'+h(run)+'/dag.html">Graph</a> · <a href="runs/'+h(run)+'/dag.json">JSON</a> · <a href="runs/'+h(run)+'/run-notes.md">Notes</a></td></tr>')
  out.append('</tbody></table></div>')
 out.append('<h2>Compare the actual graphs</h2><p>Same source packet and renderer within each pair. Select a topic. Open either graph separately for a larger view; node links lead to answers and evidence.</p><div class="tabs" role="group" aria-label="Choose topic">')
 for i,(topic,title) in enumerate(TOPICS.items()):out.append(f'<button data-topic="{topic}" aria-pressed="{str(i==0).lower()}" aria-controls="pair-{topic}">{h(title)}</button>')
 out.append('</div>')
 for i,(topic,title) in enumerate(TOPICS.items()):
  out.append(f'<section id="pair-{topic}" class="topic"'+(' hidden' if i else '')+'><h3>'+h(title)+'</h3><p class="tag">'+('Regression topic' if topic in ('evals','isolation') else 'Held out from instruction design')+'</p><div class="pair">')
  for condition,name in [('old','Current DAG instructions'),('new','Candidate DAG instructions')]:
   run=next(a['run'] for a in ASSIGN if a['topic']==topic and a['condition']==condition);g=graphs[LABELS[run]]
   out.append('<div class="panel"><h3>'+h(name)+'</h3><p>Frozen verdict: <strong>'+h(g['verdicts']['overall'].replace('_',' '))+'</strong> · <a href="runs/'+run+'/dag.html" target="_blank" rel="noopener">Open graph</a> · <a href="runs/'+run+'/dag.json">JSON</a> · <a href="runs/'+run+'/run-notes.md">Research notes</a></p><iframe loading="lazy" title="'+h(title+' — '+name)+'" src="runs/'+run+'/dag.html"></iframe></div>')
  out.append('</div></section>')
 out.append('<h2>Frozen scores by dimension</h2><p>Ordinal judgments from 1 to 5. A higher average cannot compensate for a material false dependency or missing foundation. See the review for the findings behind each score.</p><div class="table-scroll"><table><thead><tr><th>Topic</th><th>Version</th>'+''.join('<th>'+h(v)+'</th>' for v in DIMS.values())+'<th>Verdict</th></tr></thead><tbody>')
 for topic,title in TOPICS.items():
  for condition in ['old','new']:
   a=next(a for a in ASSIGN if a['topic']==topic and a['condition']==condition);g=graphs[LABELS[a['run']]]
   out.append('<tr><th>'+h(title)+'</th><td>'+('Current' if condition=='old' else 'Candidate')+'</td>'+''.join('<td>'+h(g['dimensions'].get(d,'NE'))+'</td>' for d in DIMS)+'<td>'+h(g['verdicts']['overall'].replace('_',' '))+'</td></tr>')
 out.append('</tbody></table></div><h2>Reproduce and inspect</h2><ul><li><a href="inputs/old-skill.txt">Current skill snapshot</a> · <a href="inputs/new-skill.txt">Candidate snapshot</a> · <a href="instruction-change.diff">Instruction diff</a></li><li><a href="design/benchmark/benchmark.json">Frozen benchmark</a> · <a href="design/benchmark/rubric.md">Rubric</a> · <a href="inputs/freeze-manifest.json">Input hashes</a></li><li><a href="evaluation/results.json">Structured independent results</a> · <a href="structural-checks.json">Structural checks</a> · <a href="observed/events.jsonl">Observed file states</a></li></ul><p><small>Canonical Break It Down and the original eight-report experiment are preserved. Graph renderings use the same fixed font sizes; scroll within each diagram to inspect it.</small></p></main><script>document.querySelectorAll("button[data-topic]").forEach(b=>b.addEventListener("click",()=>{document.querySelectorAll("button[data-topic]").forEach(x=>x.setAttribute("aria-pressed",String(x===b)));document.querySelectorAll(".topic").forEach(x=>x.hidden=x.id!=="pair-"+b.dataset.topic)}));</script></body></html>')
 (ROOT/'index.html').write_text(''.join(out))
if __name__=='__main__':build()
